//! Telegram MTProto API implementation.//!//! Sends encrypted RPC requests directly to Telegram's data centers via//! HTTP POST to `https://{dc}.web.telegram.org/apiw`. Uses grammers-mtproto//! (Sans-IO) for message framing and encryption; no TDLib/TDLight needed.use grammers_mtproto::mtp::Encrypted;use grammers_tl_types::{self as tl, Deserializable, Serializable};use crate::session::Session;use crate::transport;use crate::types::*;/// Current TL layer. Must match grammers-tl-types.const LAYER: i32 = 185;/// Wrap a request in InvokeWithLayer + InitConnection for the first RPC.////// Telegram requires the first request in a session to be wrapped in/// initConnection so the server knows our client metadata.fn wrap_init_connection(session: &Session, inner_bytes: Vec<u8>) -> Vec<u8> {    let init = tl::functions::InitConnection {        api_id: session.api_id,        device_model: "WASM Sandbox".to_string(),        system_version: "wasip2".to_string(),        app_version: "0.1.0".to_string(),        system_lang_code: "en".to_string(),        lang_pack: String::new(),        lang_code: "en".to_string(),        proxy: None,        params: None,        query: inner_bytes,    };    tl::functions::InvokeWithLayer {        layer: LAYER,        query: init.to_bytes(),    }    .to_bytes()}/// Create an Encrypted MTP instance from session state.fn make_mtp(session: &Session) -> Result<Encrypted, String> {    let auth_key = session.auth_key_bytes()?;    Ok(Encrypted::build()        .time_offset(session.time_offset)        .first_salt(session.first_salt)        .finish(auth_key))}/// Send an encrypted RPC, wrapping in initConnection on first call.